"""Regenerate the synthetic factor-data fixtures in this directory.

These files are SMALL, DETERMINISTIC, SYNTHETIC stand-ins (not real data) for
the downloads made by the factor services, used by
``tests/module_services/test_factors_risk_golden.py``:

Ken French Data Library layout (``fetch_ff_dataset`` zips; a zip holds one
``<name>.CSV``): a few preamble lines, a blank line, a header row whose first
cell is empty (``,Mkt-RF,SMB,...``), the data rows (``YYYYMMDD`` daily /
``YYYYMM`` monthly, values in PERCENT), then (monthly files only) an
``Annual Factors`` block, and a footer line.

* ``F-F_Research_Data_5_Factors_2x3_daily.csv``: 2024-12-02 .. 2026-05-29,
  US exchange holidays removed.
* ``F-F_Momentum_Factor_daily.csv``: same dates minus 2025-08-15 (so the
  FF5/momentum inner join visibly drops a row); header ``,Mom   ``.
* ``F-F_Research_Data_5_Factors_2x3.csv``: 2021-07 .. 2026-05 (+ annual block).
* ``F-F_Momentum_Factor.csv``: 2021-07 .. 2026-05 (+ annual block).

Hou-Xue-Zhang q-factor CSVs (read with ``pd.read_csv(url)``; percent values):

* ``q5_factors_daily_2023.csv``: ``year,month,day,R_F,R_MKT,R_ME,R_IA,R_ROE,R_EG``,
  2025-06-02 .. 2025-12-31.
* ``q5_factors_monthly_2023.csv``: ``year,month,R_F,R_MKT,...``, 2021-07 .. 2025-12.

AQR factor tables (the test turns each CSV into an .xlsx workbook in memory,
since the service reads them with ``pd.ExcelFile(url)``); month-END dates:

* ``aqr_bab_monthly.csv``: decimals, 2021-06-30 .. 2026-04-30.
* ``aqr_qmj_monthly.csv``: decimals, 2021-07-31 .. 2026-05-31.
* ``aqr_hml_devil_monthly.csv``: PERCENT (exercises the /100 branch),
  2021-07-31 .. 2026-03-31.

Run from the repo root to rewrite the files byte-for-byte::

    python tests/fixtures/ff/generate_ff_fixtures.py

Do not regenerate casually: the goldens in ``tests/goldens/factors_risk/``
are derived from these files.
"""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pandas as pd

HERE = Path(__file__).resolve().parent

DAILY_START, DAILY_END = "2024-12-02", "2026-05-29"
US_HOLIDAYS = [
    "2024-12-25", "2025-01-01", "2025-01-09", "2025-01-20", "2025-02-17",
    "2025-04-18", "2025-05-26",
    "2025-06-19", "2025-07-04", "2025-09-01", "2025-11-27", "2025-12-25",
    "2026-01-01", "2026-01-19", "2026-02-16", "2026-04-03", "2026-05-25",
]
MOM_DAILY_GAP = "2025-08-15"
MONTHLY_START, MONTHLY_END = "2021-07-01", "2026-05-01"

PREAMBLE = "_QT_TEST_ synthetic fixture - NOT real data (generated by generate_ff_fixtures.py)."
FOOTER = "_QT_TEST_ synthetic footer line"


def _daily_dates() -> pd.DatetimeIndex:
    idx = pd.bdate_range(DAILY_START, DAILY_END)
    return idx[~idx.isin(pd.to_datetime(US_HOLIDAYS))]


def _monthly_dates(start=MONTHLY_START, end=MONTHLY_END) -> pd.DatetimeIndex:
    return pd.date_range(start, end, freq="MS")


def _row(date_str: str, values, fmt: str) -> str:
    return date_str + "," + ",".join(fmt.format(v) for v in values)


def _write(name: str, lines) -> None:
    # LF endings keep git line-ending conversion out of the picture; the real
    # CRLF files are covered by an inline test.
    text = "\n".join(lines) + "\n"
    (HERE / name).write_bytes(text.encode("latin-1"))


def _ff5_daily() -> None:
    rng = np.random.default_rng(1001)
    idx = _daily_dates()
    n = len(idx)
    mkt = rng.normal(0.05, 1.0, n)
    smb = rng.normal(0.0, 0.5, n)
    hml = rng.normal(0.0, 0.6, n)
    rmw = rng.normal(0.01, 0.4, n)
    cma = rng.normal(0.0, 0.3, n)
    rf = np.where(idx < pd.Timestamp("2025-12-11"), 0.017, 0.015)
    lines = [
        "This file was created using the 202605 synthetic database.",
        "The 1-month TBill rate is a flat synthetic placeholder.",
        PREAMBLE,
        "",
        ",Mkt-RF,SMB,HML,RMW,CMA,RF",
    ]
    for i, d in enumerate(idx):
        vals = [mkt[i], smb[i], hml[i], rmw[i], cma[i]]
        lines.append(_row(d.strftime("%Y%m%d"), vals, "{:8.2f}") + f",{rf[i]:9.3f}")
    lines += ["", FOOTER]
    _write("F-F_Research_Data_5_Factors_2x3_daily.csv", lines)


def _mom_daily() -> None:
    rng = np.random.default_rng(1002)
    idx = _daily_dates()
    idx = idx[idx != pd.Timestamp(MOM_DAILY_GAP)]
    mom = rng.normal(0.03, 0.8, len(idx))
    lines = [
        "This file was created using the 202605 synthetic database.",
        "Missing data are indicated by -99.99 or -999.",
        PREAMBLE,
        "",
        ",Mom   ",
    ]
    for i, d in enumerate(idx):
        lines.append(_row(d.strftime("%Y%m%d"), [mom[i]], "{:8.2f}"))
    lines += ["", FOOTER]
    _write("F-F_Momentum_Factor_daily.csv", lines)


def _annual_block(idx, cols, data, header_label):
    """Compound monthly percent values into calendar-year rows (full years only)."""
    frame = pd.DataFrame(data, index=idx, columns=cols)
    lines = ["", header_label, "," + ",".join(cols)]
    for year, grp in frame.groupby(frame.index.year):
        if len(grp) != 12:
            continue
        ann = ((1 + grp / 100.0).prod() - 1) * 100.0
        lines.append(_row(f"{year:6d}", ann.values, "{:8.2f}"))
    return lines


def _ff5_monthly() -> None:
    rng = np.random.default_rng(1003)
    idx = _monthly_dates()
    n = len(idx)
    cols = ["Mkt-RF", "SMB", "HML", "RMW", "CMA", "RF"]
    data = np.column_stack([
        rng.normal(0.8, 4.5, n),
        rng.normal(0.0, 2.5, n),
        rng.normal(0.0, 3.0, n),
        rng.normal(0.2, 2.0, n),
        rng.normal(0.0, 1.8, n),
        np.round(np.linspace(0.01, 0.45, n), 2),
    ])
    lines = [
        "This file was created using the 202605 synthetic database.",
        "The 1-month TBill rate is a synthetic ramp.",
        PREAMBLE,
        "",
        "," + ",".join(cols),
    ]
    for i, d in enumerate(idx):
        lines.append(_row(d.strftime("%Y%m"), data[i], "{:8.2f}"))
    lines += _annual_block(idx, cols, np.round(data, 2), " Annual Factors: January-December ")
    lines += ["", FOOTER]
    _write("F-F_Research_Data_5_Factors_2x3.csv", lines)


def _mom_monthly() -> None:
    rng = np.random.default_rng(1004)
    idx = _monthly_dates()
    mom = rng.normal(0.6, 4.0, len(idx))
    lines = [
        "This file was created using the 202605 synthetic database.",
        "Missing data are indicated by -99.99 or -999.",
        PREAMBLE,
        "",
        ",Mom   ",
    ]
    for i, d in enumerate(idx):
        lines.append(_row(d.strftime("%Y%m"), [mom[i]], "{:8.2f}"))
    lines += _annual_block(idx, ["Mom"], np.round(mom, 2)[:, None], "Annual Factors:")
    lines += ["", FOOTER]
    _write("F-F_Momentum_Factor.csv", lines)


def _q5_daily() -> None:
    rng = np.random.default_rng(1005)
    idx = _daily_dates()
    idx = idx[(idx >= pd.Timestamp("2025-06-02")) & (idx <= pd.Timestamp("2025-12-31"))]
    n = len(idx)
    frame = pd.DataFrame({
        "year": idx.year, "month": idx.month, "day": idx.day,
        "R_F": np.full(n, 0.017),
        "R_MKT": np.round(rng.normal(0.06, 1.0, n), 4),
        "R_ME": np.round(rng.normal(0.0, 0.5, n), 4),
        "R_IA": np.round(rng.normal(0.0, 0.35, n), 4),
        "R_ROE": np.round(rng.normal(0.02, 0.4, n), 4),
        "R_EG": np.round(rng.normal(0.02, 0.3, n), 4),
    })
    (HERE / "q5_factors_daily_2023.csv").write_bytes(frame.to_csv(index=False, lineterminator="\n").encode())


def _q5_monthly() -> None:
    rng = np.random.default_rng(1006)
    idx = _monthly_dates(end="2025-12-01")
    n = len(idx)
    frame = pd.DataFrame({
        "year": idx.year, "month": idx.month,
        "R_F": np.round(np.linspace(0.01, 0.40, n), 4),
        "R_MKT": np.round(rng.normal(0.9, 4.5, n), 4),
        "R_ME": np.round(rng.normal(0.0, 2.5, n), 4),
        "R_IA": np.round(rng.normal(0.1, 1.8, n), 4),
        "R_ROE": np.round(rng.normal(0.3, 2.2, n), 4),
        "R_EG": np.round(rng.normal(0.4, 1.6, n), 4),
    })
    (HERE / "q5_factors_monthly_2023.csv").write_bytes(frame.to_csv(index=False, lineterminator="\n").encode())


def _aqr(name: str, seed: int, start: str, end: str, scale: float, decimals: int) -> None:
    rng = np.random.default_rng(seed)
    idx = pd.date_range(start, end, freq="ME")
    vals = np.round(rng.normal(0.004, 0.03, len(idx)) * scale, decimals)
    frame = pd.DataFrame({"DATE": idx.strftime("%Y-%m-%d"), "USA": vals})
    (HERE / name).write_bytes(frame.to_csv(index=False, lineterminator="\n").encode())


def main() -> None:
    _ff5_daily()
    _mom_daily()
    _ff5_monthly()
    _mom_monthly()
    _q5_daily()
    _q5_monthly()
    _aqr("aqr_bab_monthly.csv", 1007, "2021-06-30", "2026-04-30", 1.0, 6)
    _aqr("aqr_qmj_monthly.csv", 1008, "2021-07-31", "2026-05-31", 1.0, 6)
    _aqr("aqr_hml_devil_monthly.csv", 1009, "2021-07-31", "2026-03-31", 100.0, 4)


if __name__ == "__main__":
    main()
